//! Runtime helper functions for natively compiled spec functions.
//!
//! These are called by code generated by `native_codegen::expr_to_rust()`.
//! Each function operates directly on `RuntimeValue` and returns
//! `RuntimeResult<RuntimeValue>` (or a primitive extraction).

use crate::symbol::Symbol;
use crate::value::{RuntimeError, RuntimeResult, RuntimeValue};

/// Convenience error constructor.
#[inline]
pub fn rt_error(msg: &str) -> RuntimeError {
    RuntimeError {
        message: msg.to_string(),
    }
}

/// Extract a bool from a RuntimeValue, or error.
#[inline]
pub fn rt_expect_bool(v: &RuntimeValue) -> RuntimeResult<bool> {
    match v {
        RuntimeValue::Bool(b) => Ok(*b),
        _ => Err(rt_error(&format!(
            "expected bool, got `{}`",
            v.canonical_key()
        ))),
    }
}

/// Extract an integer from a RuntimeValue, or error.
#[inline]
pub fn rt_expect_int(v: &RuntimeValue) -> RuntimeResult<i128> {
    match v {
        RuntimeValue::Int(n) => Ok(*n),
        RuntimeValue::Nat(n) => Ok(*n as i128),
        _ => Err(rt_error(&format!(
            "expected int, got `{}`",
            v.canonical_key()
        ))),
    }
}

/// Access a named field on a struct/enum value (returns Ok(value)).
pub fn rt_field(v: &RuntimeValue, name: &str) -> RuntimeResult<RuntimeValue> {
    v.field(name).cloned().ok_or_else(|| {
        rt_error(&format!(
            "field `{}` not found on `{}`",
            name,
            v.canonical_key()
        ))
    })
}

/// Access a named field, returning the value directly (for pattern matching).
pub fn rt_field_val(v: &RuntimeValue, name: &str) -> RuntimeResult<RuntimeValue> {
    rt_field(v, name)
}

/// Index into a sequence or tuple.
pub fn rt_index(v: &RuntimeValue, idx: &RuntimeValue) -> RuntimeResult<RuntimeValue> {
    let i = rt_expect_int(idx)?;
    if i < 0 {
        return Err(rt_error(&format!("negative index {}", i)));
    }
    v.element_at(i as usize).cloned().ok_or_else(|| {
        rt_error(&format!(
            "index {} out of bounds on `{}`",
            i,
            v.canonical_key()
        ))
    })
}

/// Check if a value is a specific enum variant.
#[inline]
pub fn rt_is_variant(v: &RuntimeValue, variant: &str) -> bool {
    matches!(v, RuntimeValue::Enum { variant: v, .. } if v == variant)
}

/// Check if a value is a specific struct type.
#[inline]
pub fn rt_is_struct(v: &RuntimeValue, ty: &str) -> bool {
    matches!(v, RuntimeValue::Struct { ty: t, .. } if t == ty)
}

/// Access a field of an enum variant by positional index.
pub fn rt_variant_field(v: &RuntimeValue, idx: usize) -> RuntimeResult<RuntimeValue> {
    match v {
        RuntimeValue::Enum { fields, .. } => fields
            .iter()
            .nth(idx)
            .map(|(_, v)| v.clone())
            .ok_or_else(|| rt_error(&format!("variant field index {} out of bounds", idx))),
        _ => Err(rt_error("rt_variant_field: not an enum")),
    }
}

/// Access a tuple field by index.
pub fn rt_tuple_field(v: &RuntimeValue, idx: usize) -> RuntimeResult<RuntimeValue> {
    match v {
        RuntimeValue::Tuple(items) => items
            .get(idx)
            .cloned()
            .ok_or_else(|| rt_error(&format!("tuple index {} out of bounds", idx))),
        _ => Err(rt_error("rt_tuple_field: not a tuple")),
    }
}

/// Negate a numeric value.
pub fn rt_negate(v: &RuntimeValue) -> RuntimeResult<RuntimeValue> {
    Ok(RuntimeValue::Int(-rt_expect_int(v)?))
}

/// Binary operation on two values.
pub fn rt_binop(lhs: &RuntimeValue, op: BinOp, rhs: &RuntimeValue) -> RuntimeResult<RuntimeValue> {
    match op {
        BinOp::Add => Ok(RuntimeValue::Int(rt_expect_int(lhs)? + rt_expect_int(rhs)?)),
        BinOp::Sub => Ok(RuntimeValue::Int(rt_expect_int(lhs)? - rt_expect_int(rhs)?)),
        BinOp::Mul => Ok(RuntimeValue::Int(rt_expect_int(lhs)? * rt_expect_int(rhs)?)),
        BinOp::Div => {
            let r = rt_expect_int(rhs)?;
            if r == 0 {
                return Err(rt_error("division by zero"));
            }
            Ok(RuntimeValue::Int(rt_expect_int(lhs)? / r))
        }
        BinOp::Mod => {
            let r = rt_expect_int(rhs)?;
            if r == 0 {
                return Err(rt_error("modulo by zero"));
            }
            Ok(RuntimeValue::Int(rt_expect_int(lhs)? % r))
        }
        BinOp::And => Ok(RuntimeValue::Bool(
            rt_expect_bool(lhs)? && rt_expect_bool(rhs)?,
        )),
        BinOp::Or => Ok(RuntimeValue::Bool(
            rt_expect_bool(lhs)? || rt_expect_bool(rhs)?,
        )),
    }
}

/// Update struct/enum fields (spread syntax: `Struct { field: val, ..base }`).
pub fn rt_struct_update(
    base: &RuntimeValue,
    updates: Vec<(String, RuntimeValue)>,
) -> RuntimeResult<RuntimeValue> {
    match base {
        RuntimeValue::Struct {
            ty, fields: base_f, ..
        } => {
            let mut fields = base_f.clone();
            for (name, value) in updates {
                let sym = Symbol::intern(&name);
                fields.insert(sym, value);
            }
            Ok(RuntimeValue::struct_value_sym(ty.clone(), fields))
        }
        RuntimeValue::Enum {
            ty,
            variant,
            fields: base_f,
            ..
        } => {
            let mut fields = base_f.clone();
            for (name, value) in updates {
                let sym = Symbol::intern(&name);
                fields.insert(sym, value);
            }
            Ok(RuntimeValue::enum_value_sym(
                ty.clone(),
                variant.clone(),
                fields,
            ))
        }
        _ => Err(rt_error("rt_struct_update: not a struct or enum")),
    }
}

/// Named struct update with type name.
pub fn rt_struct_update_named(
    _ty: &str,
    base: &RuntimeValue,
    updates: Vec<(String, RuntimeValue)>,
) -> RuntimeResult<RuntimeValue> {
    rt_struct_update(base, updates)
}

/// Placeholder for match fallthrough — should be unreachable in well-typed code.
pub fn rt_match_fallthrough() -> RuntimeResult<RuntimeValue> {
    Err(rt_error("match: no arm matched"))
}

// ── Dispatch stubs ──────────────────────────────────────────────────
// These are wired to actual hook functions in Phase 38.22.1.c.v.
// For now, they're passed as function pointers through NativeContext.

/// Type alias for the hooks passed to native eval functions.
pub struct NativeContext {
    pub call_fn: Option<fn(&str, &[RuntimeValue]) -> RuntimeResult<RuntimeValue>>,
    pub method_fn: Option<fn(&RuntimeValue, &str, &[RuntimeValue]) -> RuntimeResult<RuntimeValue>>,
    pub quantifier_domain_fn: Option<fn(usize) -> RuntimeResult<Vec<RuntimeValue>>>,
    pub bounds: crate::value::RuntimeCollectionBounds,
}

/// Call a named function (dispatches through NativeContext).
pub fn rt_call(
    name: &str,
    _args: &[RuntimeValue],
    _bounds: &crate::value::RuntimeCollectionBounds,
) -> RuntimeResult<RuntimeValue> {
    // Stub — will be replaced with context-based dispatch in Phase c.v
    Err(rt_error(&format!(
        "rt_call: function `{}` not available in native mode (Phase c.v pending)",
        name
    )))
}

/// Call a method on a value (dispatches through NativeContext).
pub fn rt_method_call(
    _recv: &RuntimeValue,
    method: &str,
    _args: &[RuntimeValue],
    _bounds: &crate::value::RuntimeCollectionBounds,
) -> RuntimeResult<RuntimeValue> {
    // Stub — will be replaced with context-based dispatch in Phase c.v
    Err(rt_error(&format!(
        "rt_method_call: method `{}` not available in native mode (Phase c.v pending)",
        method
    )))
}

/// Get the domain for a quantifier variable (dispatches through NativeContext).
pub fn rt_quantifier_domain(binding_index: usize) -> RuntimeResult<Vec<RuntimeValue>> {
    // Stub — will be replaced with context-based dispatch in Phase c.v
    Err(rt_error(&format!(
        "rt_quantifier_domain: binding {} not available in native mode (Phase c.v pending)",
        binding_index
    )))
}

/// BinOp enum — mirrors `crate::ast::BinOp` for use in generated code.
/// Defined here so generated code doesn't depend on the transpiler's AST module.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    And,
    Or,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_rt_expect_bool() {
        assert_eq!(rt_expect_bool(&RuntimeValue::Bool(true)).unwrap(), true);
        assert!(rt_expect_bool(&RuntimeValue::Int(1)).is_err());
    }

    #[test]
    fn test_rt_expect_int() {
        assert_eq!(rt_expect_int(&RuntimeValue::Int(42)).unwrap(), 42);
        assert_eq!(rt_expect_int(&RuntimeValue::Nat(10)).unwrap(), 10);
        assert!(rt_expect_int(&RuntimeValue::Bool(true)).is_err());
    }

    #[test]
    fn test_rt_field() {
        let v =
            RuntimeValue::struct_value("S", vec![("x".to_string(), RuntimeValue::Int(1))]).unwrap();
        assert_eq!(rt_field(&v, "x").unwrap(), RuntimeValue::Int(1));
        assert!(rt_field(&v, "y").is_err());
    }

    #[test]
    fn test_rt_index() {
        let v = RuntimeValue::Seq(std::sync::Arc::new(vec![
            RuntimeValue::Int(10),
            RuntimeValue::Int(20),
        ]));
        assert_eq!(
            rt_index(&v, &RuntimeValue::Int(0)).unwrap(),
            RuntimeValue::Int(10)
        );
        assert_eq!(
            rt_index(&v, &RuntimeValue::Int(1)).unwrap(),
            RuntimeValue::Int(20)
        );
        assert!(rt_index(&v, &RuntimeValue::Int(2)).is_err());
        assert!(rt_index(&v, &RuntimeValue::Int(-1)).is_err());
    }

    #[test]
    fn test_rt_is_variant() {
        let v = RuntimeValue::enum_value_sym(
            "Color",
            "Red",
            std::iter::empty::<(Symbol, RuntimeValue)>(),
        );
        assert!(rt_is_variant(&v, "Red"));
        assert!(!rt_is_variant(&v, "Blue"));
    }

    #[test]
    fn test_rt_is_struct() {
        let v =
            RuntimeValue::struct_value("S", vec![("x".to_string(), RuntimeValue::Int(1))]).unwrap();
        assert!(rt_is_struct(&v, "S"));
        assert!(!rt_is_struct(&v, "T"));
    }

    #[test]
    fn test_rt_negate() {
        assert_eq!(
            rt_negate(&RuntimeValue::Int(5)).unwrap(),
            RuntimeValue::Int(-5)
        );
    }

    #[test]
    fn test_rt_binop_add() {
        let r = rt_binop(&RuntimeValue::Int(3), BinOp::Add, &RuntimeValue::Int(4)).unwrap();
        assert_eq!(r, RuntimeValue::Int(7));
    }

    #[test]
    fn test_rt_binop_div_by_zero() {
        assert!(rt_binop(&RuntimeValue::Int(1), BinOp::Div, &RuntimeValue::Int(0)).is_err());
    }

    #[test]
    fn test_rt_struct_update() {
        let base = RuntimeValue::struct_value(
            "S",
            vec![
                ("x".to_string(), RuntimeValue::Int(1)),
                ("y".to_string(), RuntimeValue::Int(2)),
            ],
        )
        .unwrap();
        let updated =
            rt_struct_update(&base, vec![("x".to_string(), RuntimeValue::Int(99))]).unwrap();
        assert_eq!(updated.field("x"), Some(&RuntimeValue::Int(99)));
        assert_eq!(updated.field("y"), Some(&RuntimeValue::Int(2)));
    }

    #[test]
    fn test_rt_tuple_field() {
        let v = RuntimeValue::Tuple(vec![RuntimeValue::Int(1), RuntimeValue::Bool(true)]);
        assert_eq!(rt_tuple_field(&v, 0).unwrap(), RuntimeValue::Int(1));
        assert_eq!(rt_tuple_field(&v, 1).unwrap(), RuntimeValue::Bool(true));
        assert!(rt_tuple_field(&v, 2).is_err());
    }

    #[test]
    fn test_rt_variant_field() {
        let v = RuntimeValue::enum_value(
            "Msg",
            "Send",
            vec![("data".to_string(), RuntimeValue::Int(42))],
        )
        .unwrap();
        assert_eq!(rt_variant_field(&v, 0).unwrap(), RuntimeValue::Int(42));
        assert!(rt_variant_field(&v, 1).is_err());
    }

    #[test]
    fn test_rt_match_fallthrough() {
        assert!(rt_match_fallthrough().is_err());
    }
}
